// Entrada compatible con AgentFlow / BotIvA: body.payload o body plano
const body = $input.first().json.body || $input.first().json;
const payload = body.payload || body;

const limit = Math.min(Math.max(Number(payload.limit) || 8, 1), 25);
const topic = String(payload.topic || payload.categoria || 'world').toLowerCase();
const lang = String(payload.lang || payload.idioma || 'es').toLowerCase();
const source = String(payload.source || 'google').toLowerCase();

const GOOGLE_TOPICS = {
  world: 'WORLD',
  mundo: 'WORLD',
  business: 'BUSINESS',
  negocios: 'BUSINESS',
  technology: 'TECHNOLOGY',
  tech: 'TECHNOLOGY',
  science: 'SCIENCE',
  ciencia: 'SCIENCE',
  health: 'HEALTH',
  salud: 'HEALTH',
};

const hl = lang === 'en' ? 'en-US' : 'es-419';
const gl = lang === 'en' ? 'US' : 'MX';
const ceid = lang === 'en' ? 'US:en' : 'MX:es-419';
const gTopic = GOOGLE_TOPICS[topic] || 'WORLD';

const feeds = {
  google: `https://news.google.com/rss/headlines/section/topic/${gTopic}?hl=${hl}&gl=${gl}&ceid=${ceid}`,
  bbc_world: 'http://feeds.bbci.co.uk/news/world/rss.xml',
  bbc_latam: 'http://feeds.bbci.co.uk/news/world/latin_america/rss.xml',
  bbc_business: 'http://feeds.bbci.co.uk/news/business/rss.xml',
  bbc_tech: 'http://feeds.bbci.co.uk/news/technology/rss.xml',
};

let feedUrl = feeds.google;
if (source === 'bbc' || source === 'bbc_world') feedUrl = feeds.bbc_world;
else if (source === 'bbc_latam' || source === 'latam') feedUrl = feeds.bbc_latam;
else if (source === 'bbc_business') feedUrl = feeds.bbc_business;
else if (source === 'bbc_tech') feedUrl = feeds.bbc_tech;

return [{
  json: {
    limit,
    topic,
    lang,
    source,
    feedUrl,
    queriedAt: new Date().toISOString(),
  },
}];

const config = $('Parámetros consulta').first().json;
const limit = config.limit || 8;

const items = $input.all().map((i) => i.json);

const noticias = items.slice(0, limit).map((item, idx) => {
  const title = item.title || item.json?.title || 'Sin título';
  const link = item.link || item.json?.link || '';
  const pubDate = item.pubDate || item.isoDate || item.published || '';
  const snippet = (item.contentSnippet || item.content || item.summary || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 280);
  const sourceName = item.creator || item['dc:creator'] || config.source;

  return {
    rank: idx + 1,
    titulo: title,
    enlace: link,
    fecha: pubDate,
    resumen: snippet || null,
    fuente: sourceName,
  };
});

const resumenTexto = noticias.length
  ? noticias.map((n) => `${n.rank}. ${n.titulo} (${n.fecha || 'sin fecha'})`).join('\n')
  : 'No se encontraron titulares en el feed RSS.';

return [{
  json: {
    ok: true,
    action: 'noticias_mundiales',
    total: noticias.length,
    topic: config.topic,
    lang: config.lang,
    source: config.source,
    feedUrl: config.feedUrl,
    queriedAt: config.queriedAt,
    summary: `Top ${noticias.length} noticias (${config.topic}, ${config.lang}, fuente ${config.source}).`,
    resumenTexto,
    noticias,
    note: 'RSS gratuito (Google News / BBC). Parámetros opcionales en payload: limit, topic, lang, source.',
  },
}];
